package com.benoduor.jobtracker.controller;
import com.benoduor.jobtracker.model.ApplicationEvent; import com.benoduor.jobtracker.service.EventService; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/v1/events") public class EventController { private final EventService service; public EventController(EventService service){this.service=service;} @PostMapping public Map<String,Object> record(@RequestBody ApplicationEvent event){ return Map.of("accepted",true,"eventCount",service.record(event)); } @GetMapping("/stats") public Map<String,Object> stats(){return Map.of("eventCount",service.count());} @GetMapping("/health") public Map<String,String> health(){return Map.of("status","ok","service","job-tracker-events");} }
